import heapq

def match(orders):
    trades = []
    book = {}  # id -> [side, price, qty, seq, active]
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def clean_buy():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info[4] or info[2] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info[4] or info[2] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info[4] and info[2] > 0:
                info[4] = False
            continue

        oid = order[1]
        side = order[2]
        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                s_price, s_seq, s_id = sell_heap[0]
                if typ != 'market' and price < s_price:
                    break
                s_info = book[s_id]
                trade_qty = min(remaining, s_info[2])
                trades.append([oid, s_id, s_price, trade_qty])
                remaining -= trade_qty
                s_info[2] -= trade_qty
                if s_info[2] <= 0:
                    s_info[4] = False
                    heapq.heappop(sell_heap)
            if typ == 'limit' and remaining > 0:
                seq_counter += 1
                book[oid] = ['buy', price, remaining, seq_counter, True]
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negprice, b_seq, b_id = buy_heap[0]
                b_price = -negprice
                if typ != 'market' and price > b_price:
                    break
                b_info = book[b_id]
                trade_qty = min(remaining, b_info[2])
                trades.append([b_id, oid, b_price, trade_qty])
                remaining -= trade_qty
                b_info[2] -= trade_qty
                if b_info[2] <= 0:
                    b_info[4] = False
                    heapq.heappop(buy_heap)
            if typ == 'limit' and remaining > 0:
                seq_counter += 1
                book[oid] = ['sell', price, remaining, seq_counter, True]
                heapq.heappush(sell_heap, (price, seq_counter, oid))

    return trades

